const R26_C4_VOCATION_VIEW_CACHE=new Map();
function r26c4VocationPanelCache(entity){
  const key=keyOf(entity),current=entity?(graph(entity)||{}):{};const hit=R26_C4_VOCATION_VIEW_CACHE.get(key);if(hit&&hit.current===current)return hit;
  const rows=[...(current.shared_progression?.panels||[])];for(const variant of current.character_variants||[])rows.push(...(variant?.panels||[]));
  const panels=[],byId=new Map();for(const panel of rows){const id=String(panel?.row?.id??'');if(!id||byId.has(id))continue;byId.set(id,panel);panels.push(panel)}
  const built={current,panels,byId};R26_C4_VOCATION_VIEW_CACHE.set(key,built);return built;
}
