// SMASHDUMP_ENCYCLOPEDIA_BROWSER_INTEGRATION_R5_4_RUNTIME_SHIM
(() => {
  const R54_MARKER = 'r5-4';

  function r54Esc(value) {
    if (typeof esc === 'function') return esc(value);
    return String(value ?? '').replace(/[&<>"']/g, c => ({
      '&': '&amp;', '<': '&lt;', '>': '&gt;',
      '"': '&quot;', "'": '&#39;'
    })[c]);
  }

  function r54GameImage(entity, className = 'entity-game-image') {
    const asset = entity?.game_asset;
    if (!asset?.url) return '?';
    return `<img class="${r54Esc(className)}" src="${r54Esc(asset.url)}" alt="" loading="lazy" draggable="false" data-r5-4-image="1">`;
  }

  function r54ImageStatusBadge(entity) {
    const status = entity?.image_status;
    if (!status) return '';
    const text = String(status).replaceAll('_', ' ');
    const cls =
      status === 'EXACT_MATCH' ? 'added' :
      status === 'INHERITED_RELATION' ? 'modified' :
      status.includes('UNRESOLVED') ||
      status.includes('NO_EXPLICIT') ? 'missing' : 'unchanged';
    return `<span class="badge ${cls}" data-r5-4-image-status="1" title="Image Closure R4 status">${r54Esc(text)}</span>`;
  }

  function r54ImageGallery(entity) {
    const assets = entity?.game_assets || [];
    const status = entity?.image_status || 'UNKNOWN';
    const review = entity?.image_review || {};
    if (!assets.length) {
      const unresolved = (review.unresolved || [])
        .map(value => value.logical_path)
        .filter(Boolean)
        .join(' · ');
      return `<div class="image-closure-note status-${r54Esc(String(status).toLowerCase())}" data-r5-4-gallery="1"><strong>${r54Esc(status)}</strong><span>No reliable image was assigned automatically. This entry remains in the accepted review queue.</span>${unresolved ? `<small>${r54Esc(unresolved)}</small>` : ''}</div>`;
    }
    return `<div class="entity-image-gallery" data-r5-4-gallery="1">${assets.slice(0, 30).map(asset =>
      `<figure><a href="${r54Esc(asset.url)}" target="_blank" rel="noopener"><img src="${r54Esc(asset.url)}" alt="" loading="lazy"></a><figcaption><strong>${r54Esc(asset.role || 'image')}</strong><span>${r54Esc(asset.match_method || 'resolved')} · ${Math.round(Number(asset.confidence || 0) * 100)}%</span><code>${r54Esc(asset.logical_path || asset.source_bundle_path || '')}</code></figcaption></figure>`
    ).join('')}</div>`;
  }

  function r54IsVersionChange(entity) {
    const status = String(entity?.status || '');
    return status === 'Modified' || status.startsWith('Added');
  }

  function r54EntityForCard(card) {
    const key = card?.dataset?.key;
    if (!key || typeof findByKey !== 'function') return null;
    try {
      return findByKey(key);
    } catch {
      return null;
    }
  }

  function r54ApplyCardImages() {
    document.querySelectorAll('.entity-card[data-key]').forEach(card => {
      const entity = r54EntityForCard(card);
      if (!entity) return;

      const thumb = card.querySelector('.thumb');
      if (thumb) {
        thumb.innerHTML = r54GameImage(entity, 'entity-thumb-image');
        thumb.dataset.r54Applied = '1';
      }

      const badges = card.querySelector('.badges');
      if (
        badges &&
        entity.image_status &&
        !badges.querySelector('[data-r5-4-image-status]')
      ) {
        badges.insertAdjacentHTML(
          'beforeend',
          r54ImageStatusBadge(entity)
        );
      }
    });
  }

  function r54ApplyDetailImage(entity) {
    const panel = document.getElementById('detailPanel');
    if (!panel || !entity) return;

    const art = panel.querySelector('.detail-art');
    if (art) {
      art.innerHTML = r54GameImage(entity, 'detail-game-image');
      art.dataset.r54Applied = '1';
    }

    const badges = panel.querySelector('.badges');
    if (
      badges &&
      entity.image_status &&
      !badges.querySelector('[data-r5-4-image-status]')
    ) {
      badges.insertAdjacentHTML(
        'beforeend',
        r54ImageStatusBadge(entity)
      );
    }

    if (
      panel.querySelector('[data-r5-4-gallery]') ||
      panel.querySelector('.entity-image-gallery')
    ) {
      return;
    }

    const sections = [...panel.querySelectorAll('details.section')];
    const assetsSection = sections.find(section => {
      const summary = section.querySelector(':scope > summary');
      const label = String(summary?.textContent || '').trim().toLowerCase();
      return (
        label.includes('asset') ||
        label.includes('internal path') ||
        label.includes('game file')
      );
    });

    const content =
      assetsSection?.querySelector(':scope > .section-content') ||
      assetsSection?.querySelector('.section-content');

    if (content) {
      content.insertAdjacentHTML(
        'afterbegin',
        r54ImageGallery(entity)
      );
    }
  }

  function r54EnsureChrome() {
    let changes = document.getElementById('changesButton');
    if (!changes) {
      const filter = document.getElementById('filterButton');
      const toolbar = filter?.parentElement || document.querySelector('.toolbar');
      if (toolbar) {
        changes = document.createElement('button');
        changes.id = 'changesButton';
        changes.type = 'button';
        changes.className = 'toolbar-button';
        changes.title =
          'Show only entries added or modified between the selected versions';
        changes.innerHTML = '<span>Δ</span> Changes only';
        if (filter?.nextSibling) {
          toolbar.insertBefore(changes, filter.nextSibling);
        } else {
          toolbar.appendChild(changes);
        }
      }
    }

    if (changes) {
      changes.classList.toggle('active', Boolean(state.onlyChanges));
      changes.onclick = () => {
        state.onlyChanges = !state.onlyChanges;
        localStorage.setItem(
          'sd-ency-only-changes',
          state.onlyChanges ? '1' : '0'
        );
        renderAll();
        if (typeof toast === 'function') {
          toast(
            state.onlyChanges
              ? 'Showing added and modified entries'
              : 'Showing all version statuses'
          );
        }
      };
    }

    document.querySelectorAll('[data-r5-4-image-review], .image-review-tab').forEach(node => node.remove());
  }

  state.onlyChanges =
    localStorage.getItem('sd-ency-only-changes') === '1';

  const r54BaseFiltered = filtered;
  filtered = function(...args) {
    const rows = r54BaseFiltered.apply(this, args);
    if (!state.onlyChanges) return rows;
    return rows.filter(r54IsVersionChange);
  };

  const r54BaseRenderList = renderList;
  renderList = function(...args) {
    const result = r54BaseRenderList.apply(this, args);
    r54ApplyCardImages();
    r54EnsureChrome();
    return result;
  };

  const r54BaseRenderDetail = renderDetail;
  renderDetail = function(entity, ...args) {
    const result = r54BaseRenderDetail.call(this, entity, ...args);
    r54ApplyDetailImage(entity);
    r54EnsureChrome();
    return result;
  };

  const r54BaseRenderAll = renderAll;
  renderAll = function(...args) {
    const result = r54BaseRenderAll.apply(this, args);
    r54EnsureChrome();
    r54ApplyCardImages();
    return result;
  };

  // init() may already be waiting on fetch(). The promise callback will use
  // these wrapped function bindings. This timeout also covers cached/manual
  // data states and creates the toolbar controls immediately.
  setTimeout(() => {
    r54EnsureChrome();
    if (state.data) renderAll();
  }, 0);

  globalThis.__SMASHDUMP_R5_4_IMAGE_INTEGRATION__ = {
    marker: R54_MARKER,
    applyCards: r54ApplyCardImages,
    applyDetail: r54ApplyDetailImage,
    ensureChrome: r54EnsureChrome
  };
})();

