    const groupHtml=groups.map(([key,label])=>{const items=bonuses.filter(row=>row.section===key);if(!items.length)return'';return `<section class="s3r24-bonus-group"><h5>${esc(label)}</h5><div>${items.map(row=>`<article class="s3r24-bonus-row"><span class="s3r24-bonus-icon" aria-hidden="true">${esc(row.icon)}</span><div class="s3r24-bonus-copy"><strong>${esc(row.name)}</strong>${row.description?`<p>${esc(row.description)}</p>`:''}${row.badges.length?`<div class="s3r24-badges">${row.badges.map(badge=>`<span><i aria-hidden="true">${esc(badge.icon)}</i>${esc(badge.label)}</span>`).join('')}</div>`:''}</div><b>${esc(row.value)}</b></article>`).join('')}</div></section>`}).join('');
