  function updateTechnical(panel,memory,rank){const pre=panel?.querySelector('[data-s3r32-technical]');if(pre)pre.textContent=JSON.stringify(technicalPayload(memory,rank),null,2)}
  function wireRankTabsR32(x){const panel=document.getElementById('detailPanel'),memory=memoryFor(x);if(!panel||!memory)return;wireRankChangeAnchors(panel);const memoryKey=keyOf(x);panel.querySelectorAll('.s3r32-rank-tabs .rank-tab').forEach(button=>button.onclick=()=>{const rank=rankFor(memory,button.dataset.rank);if(!rank)return;const content=panel.querySelector('#memoryRankContent');captureOpen(content,memoryKey);state.memoryRank.set(memoryKey,rank.rank_name);panel.querySelectorAll('.s3r32-rank-tabs .rank-tab').forEach(node=>node.classList.toggle('active',node===button));const visual=panel.querySelector('#s3r32MemoryVisual');if(visual)visual.innerHTML=r31.memoryVisual(memory,rank);if(content){content.innerHTML=memoryRankBlockR32(x,rank);restoreOpen(content,memoryKey)}updateTechnical(panel,memory,rank);bindLinks(panel)})}
  renderDetail=function(x,...args){const result=oldRenderDetail.call(this,x,...args);if(x?.category==='memories'){wireRankTabsR32(x);bindLinks(document.getElementById('detailPanel')||document)}return result};
  r3.ready.then(()=>{if(![PATCH_ID,'SMASHDUMP_STAGE3_R3_3_MEMORY_COLOUR_BONUS_AND_BANNER_PRESENTATION'].includes(r3.model?.revision_patch_id))console.warn('Stage 3 R3.2 model revision marker was not found');if(state.data)renderAll()});
  globalThis.__SMASHDUMP_STAGE3_R3_2__={marker:PATCH_ID,memoryFor,rankFor,memoryDetailR32,memoryRankBlockR32,wireRankTabsR32,acquisitionSection,rankChanges};
