  const baseCardFacts=cardFacts;
  const basePassesFilters=passesFilters;
  const baseSortOptions=sortOptions;
  const baseCompareRows=compareRows;
  const baseRenderFilterDrawer=renderFilterDrawer;
  const baseFilterActiveCount=filterActiveCount;
  const baseFilterChips=filterChips;
  const baseRenderDetail=renderDetail;
  const baseRenderAll=renderAll;
  let model=null;
  let aliases=new Map();
  state.r41Variant=state.r41Variant||new Map();
