      if(f.r4Tags.length&&!selectedAny(f.r4Tags,family.tags||[]))return false;
      const elements=family.kind==='skill'?(family.element?.name?[family.element.name]:[]):[...new Set((family.variants||[]).flatMap(v=>(v.elements||[]).map(e=>e.name)))];
