  sortOptions=function(){if(!worldCategories.includes(state.category)||!model)return previousSortOptions();const base=[['name-asc','Name · A–Z'],['name-desc','Name · Z–A']];if(['events','shops','gacha'].includes(state.category))base.push(['runtime-asc','Availability · active first']);if(state.category==='enemies')base.push(['contexts-desc','Stage appearances · high to low'],['hp-desc','Highest recorded HP · high to low']);if(state.category==='stages')base.push(['stage-order-asc','Game / event order'],['difficulty-asc','Difficulty']);if(state.category==='items')base.push(['sources-desc','Acquisition routes · high to low']);return base};
