  filterChips=function(){const base=previousFilterChips();if(!worldCategories.includes(state.category))return base;const f=filterState();for(const [key,label] of [['r51Availability','Availability'],['r51Difficulty','Difficulty'],['r51GroupType','Stage type'],['r51Source','Source'],['r51EventType','Event type']])for(const value of f[key])base.push({key,value,label:`${label}: ${value}`});return base};
