  const section=(title,body,count=null,open=false,extra='')=>`<details class="section s3r52-section ${extra}" ${open?'open':''}><summary><span>${esc(title)}</span>${count!==null?`<b>${fmtN(count)}</b>`:''}</summary><div class="section-content">${body}</div></details>`;
