    const grades=c.reference_closure_season_grade_rewards?.rows||[],ranking=c.reference_closure_season_ranking_rewards?.rows||[];
    const grouped=(rows,key,fallback)=>{const groups=new Map();for(const row of rows){const value=String(row.display_label||row[key]||fallback);if(!groups.has(value))groups.set(value,[]);groups.get(value).push(row)}return [...groups.entries()].map(([value,items])=>{const p=items.map(x=>x?.rank_presentation).find(Boolean)||{},plate=p.plate_asset||{},text=p.text_asset||{},cssAsset=raw=>{const a=r81AcceptedAsset(raw),src=r813AssetPrimary(a),resolved=src?new URL(src,document.baseURI).href:'';return resolved?`url('${esc(resolved)}')`:'none'},style=` style="--s3r517-rank-bg:${cssAsset(plate)};--s3r517-rank-text:${cssAsset(text)};--s3r517-rank-accent-a:${esc(p.accent_start||'#27313d')};--s3r517-rank-accent-b:${esc(p.accent_end||'#53657a')}"`,textTransform=String((r81AcceptedAsset(text)||{}).presentation_transform||'native'),transformClass=textTransform==='flip-y'?' s3r813-rank-text-flip':'',family=String(p.family||'Unknown').toLowerCase().replace(/[^a-z0-9]+/g,'-');return `<article class="s3r517-reward-group s3r517r2-gauntlet-group s3r517r4-rank-card s3r517r5-rank-card s3r517r5-rank-${esc(family)}${transformClass}" data-rank-presentation-source="${esc(p.source||'missing')}" data-rank-family="${esc(p.family||'Unknown')}"${style}><strong>${esc(value)}</strong><div>${items.map(x=>contentHtml(x.reward)).join('')}</div></article>`}).join('')};
