    const hierarchy=(c.hierarchy||[]).map((g,i)=>section(g.title,`${g.asset?img(g.asset,'s3r52-group-banner',g.title):''}${g.description?`<p>${esc(g.description)}</p>`:''}<div class="s3r52-stage-links">${(g.stages||[]).map(s=>{const st=model.categories.stages[String(s.id)];return `<article>${img(st?.display_asset,'s3r52-stage-thumb',s.name)}<div><strong>${link(s)}</strong><small>${esc(st?.current?.difficulty||'')}</small></div></article>`}).join('')}</div>`,g.stages?.length||0,i<2,'s3r52-event-group')).join('');
