    return `<div class="s3r52-effect-hero">${img(row.display_asset,'s3r52-boon-art',row.name?.text||'')}<div><span>Event effect</span><strong>${esc(c.effect_text||row.description?.text||'')}</strong></div></div>${grid([['Event',c.event?c.event.name:null],['Ranks',c.rank_count||1],['Supported stages',c.supported_stage_count||0],['Expires',c.expires_utc?new Date(c.expires_utc).toLocaleString():null]])}${c.event?`<p>${link(c.event)}</p>`:''}${c.rank_count>1?section('Rank progression',`<div class="s3r52-boon-ranks">${ranks}</div>`,c.rank_count,true):''}${groups?section('Supported event areas',groups,c.supported_groups?.length||0):''}${technical({evidence:row.evidence,ranks:c.ranks})}`;
