    const draws=(c.draws||[]).map(draw=>{const p=draw.payment||{};return `<article class="s3r52-draw"><header><strong>${fmtN(draw.draw_count)} draw${Number(draw.draw_count)===1?'':'s'}</strong><span>${img(p.asset,'s3r52-currency-art',p.name||'')}${fmtN(p.amount)} ${esc(p.name||'Unresolved payment')}</span>${draw.stamp_progress?'<span class="chip">Advances stamp card</span>':''}</header><div class="s3r52-rates">${(draw.rarity_rates||[]).map(r=>`<div><strong>${starsFromRaw(r.rarity)}★</strong><span>${r.rate_percent!==null&&r.rate_percent!==undefined?`${fmtN(r.rate_percent)}%`:'Rate unavailable'}</span><small>${fmtN(r.pool_count||0)} items in pool</small></div>`).join('')}</div></article>`}).join('');
    const cards=(c.stamp_positions||[]).map(card=>section(`Stamp card ${card.card}`,(card.rewards||[]).map(entry=>`<div class="s3r52-stamp"><strong>Stamp ${fmtN(entry.stamp)}</strong>${contentHtml(entry.reward)}</div>`).join(''),card.rewards?.length||0,card.card===1)).join('');
    return `${row.display_asset?img(row.display_asset,'s3r52-gacha-banner',row.name?.text||''):''}${grid([['Availability',status],['Featured pickups',c.pickups?.length||0],['Draw options',c.draws?.length||0],['Stamp cards',c.stamp_positions?.length||0],['Ends',c.end_utc?new Date(c.end_utc).toLocaleString():'No end date recorded']])}${section('Featured pickups',pickups,c.pickups?.length||0,true)}${section('Draw costs and rarity rates',draws,c.draws?.length||0,true)}${c.stamp_positions?.length?section('Stamp-card rewards',cards,c.stamp_positions.length):''}${technical({gacha_id:entity.id})}`;
