    const frame=document.createElement('div');frame.className='s3r513r2-banner';
    const image=document.createElement('img');image.alt='';image.loading='lazy';image.decoding='async';image.draggable=false;
    image.src=asset.url||asset.fallback_url;
    image.addEventListener('error',()=>{if(asset.fallback_url&&image.dataset.fallbackApplied!=='1'){image.dataset.fallbackApplied='1';image.src=asset.fallback_url}else frame.remove()},{once:false});
    frame.append(image);return frame;
