    const selected=context.selectedKeys.has(node.key);
    details.open=selected||state.r513r2Open.has(node.key)||(!state.r513r2Initialized&&context.takeDefault());
    details.append(summary(node,depth));
    const body=document.createElement('div');body.className='s3r513r2-event-body';
