    const selected=context.selectedKeys.has(node.key);
    details.open=selected||state.r513r2Open.has(node.key)||(!state.r513r2Initialized&&index===0);
    details.append(summary(node,0));
    const body=document.createElement('div');body.className='s3r513r2-collection-body';
    if(node.items.length)body.append(cardsGrid(node.items));
