  const diagnostics={attempts:0,successes:0,last_reason:null,last_error:null,stage_entities:0,model_rows:0,certified:0,roots:0};

  state.r513r5Open=new Set(); // Corrected R10: Stage collections start closed and thereafter follow explicit user toggles only.
  state.r513r5Tabs=state.r513r5Tabs||state.r513r4Tabs||state.r513r2Tabs||new Map();
